<script setup lang="ts">
import {computed,nextTick,onBeforeUnmount,ref,watch} from 'vue'
import Icon from './AppIcon.vue'
const props=defineProps<{modelValue:string;open:boolean;supported:boolean}>()
const emit=defineEmits<{'update:open':[value:boolean];select:[value:string]}>()
const trigger=ref<HTMLButtonElement>(),menu=ref<HTMLElement>(),position=ref({left:'0px',top:'0px',visibility:'hidden' as 'hidden'|'visible'})
const options=[{value:'',label:'供应商默认'},{value:'none',label:'关闭思考'},{value:'low',label:'快速思考'},{value:'high',label:'深入思考'},{value:'max',label:'最大思考'}]
const label=computed(()=>options.find(o=>o.value===props.modelValue)?.label||'供应商默认')
function place(){if(!menu.value)return;const a=trigger.value?.getBoundingClientRect()||{top:window.innerHeight-160,bottom:window.innerHeight-130,right:window.innerWidth-16},h=menu.value.offsetHeight,w=menu.value.offsetWidth,gap=8;const above=a.top-h-gap;position.value={left:Math.max(8,Math.min(a.right-w,window.innerWidth-w-8))+'px',top:Math.max(8,above>=8?above:Math.min(a.bottom+gap,window.innerHeight-h-8))+'px',visibility:'visible'}}
function close(focus=true){emit('update:open',false);if(focus)trigger.value?.focus()}
function outside(e:PointerEvent){if(!menu.value?.contains(e.target as Node)&&!trigger.value?.contains(e.target as Node))close(false)}
function key(e:KeyboardEvent){if(e.key==='Escape'){e.preventDefault();e.stopPropagation();close();return}const items=Array.from(menu.value?.querySelectorAll<HTMLButtonElement>('[role="menuitemradio"]')||[]);if(['ArrowDown','ArrowUp','Home','End'].includes(e.key)){e.preventDefault();const i=items.indexOf(document.activeElement as HTMLButtonElement),next=e.key==='Home'?0:e.key==='End'?items.length-1:(i+(e.key==='ArrowDown'?1:-1)+items.length)%items.length;items[next]?.focus()}if(e.key==='Tab')close(false)}
function choose(value:string){emit('select',value);close()}
watch(()=>props.open,async value=>{if(value){await nextTick();place();await nextTick();menu.value?.querySelector<HTMLButtonElement>('[aria-checked="true"]')?.focus();document.addEventListener('pointerdown',outside,true);window.addEventListener('resize',place);window.addEventListener('scroll',place,true)}else cleanup()})
function cleanup(){document.removeEventListener('pointerdown',outside,true);window.removeEventListener('resize',place);window.removeEventListener('scroll',place,true)}
onBeforeUnmount(cleanup)
</script>
<template><button v-if="supported" ref="trigger" type="button" class="composer-reasoning-trigger" aria-label="设置思考程度" aria-haspopup="menu" :aria-expanded="open" @click="emit('update:open',!open)" @keydown.down.prevent="emit('update:open',true)"><Icon name="Brain" :size="14"/><span>{{label}}</span><Icon name="ChevronDown" :size="11"/></button><Teleport to="body"><div v-if="open" ref="menu" class="orbit-reasoning-menu" :style="position" role="menu" aria-label="思考程度设置" @keydown="key"><template v-if="supported"><span class="orbit-menu-caption">思考程度</span><button v-for="option in options" :key="option.value" role="menuitemradio" :aria-checked="modelValue===option.value" type="button" @click="choose(option.value)"><span>{{option.label}}</span><Icon v-if="modelValue===option.value" name="Check" :size="14"/></button></template><p v-else>当前模型尚未验证支持思考程度设置。</p></div></Teleport></template>
<style>
.composer-reasoning-trigger{display:inline-flex;align-items:center;gap:4px;min-width:0;height:30px;padding:0 5px;border-radius:7px;color:var(--muted);font-size:11px;white-space:nowrap}.composer-reasoning-trigger:hover,.composer-reasoning-trigger[aria-expanded=true]{background:var(--purple-soft);color:var(--text)}.composer-reasoning-trigger>span{max-width:64px;overflow:hidden;text-overflow:ellipsis}.orbit-reasoning-menu{position:fixed;z-index:1000;box-sizing:border-box;width:min(252px,calc(100vw - 16px));padding:6px;border:1px solid var(--border);border-radius:11px;background:var(--surface-raised);box-shadow:0 8px 28px #21173518;color:var(--text);font-family:inherit;animation:orbit-menu-appear 140ms ease-out}.orbit-menu-caption{display:block;padding:5px 9px;font-size:11px;color:var(--muted)}.orbit-reasoning-menu>button{display:flex;align-items:center;justify-content:space-between;box-sizing:border-box;width:100%;height:32px;padding:0 9px;border:0;border-radius:6px;background:transparent;color:var(--text);font:inherit;font-size:12px;font-weight:400;text-align:left;cursor:pointer;transition:background-color 150ms,color 150ms}.orbit-reasoning-menu>button:hover,.orbit-reasoning-menu>button:focus-visible{background:var(--purple-soft);outline:2px solid transparent}.orbit-reasoning-menu>button[aria-checked=true]{background:var(--compose-bg)}.orbit-reasoning-menu>button:focus-visible{outline-color:var(--purple);outline-offset:-2px}.orbit-reasoning-menu p{font-size:12px;line-height:1.6;padding:8px}@keyframes orbit-menu-appear{from{opacity:0}to{opacity:1}}@media(prefers-reduced-motion:reduce){.orbit-reasoning-menu{animation:none}.orbit-reasoning-menu>button{transition:none}}@media(max-width:1250px){.composer-reasoning-trigger>span{max-width:44px}}
</style>
